// Custom Space — logic (Rune). Editor::new declares the params and
// triggers the panel binds to by id (ui.knob('amount'), ui.button('go')).

pub fn describe() {
  Editor::new("Space").knob("amount", 0.0, 1.0, 0.5).trigger("go")
}

pub fn new() { #{ amount: 0.5 } }

pub fn param(state, id, value) {
  if id == "amount" { state.amount = value; }
}

pub fn trigger(state, id, args) {
  emit(id, #{ amount: state.amount });
  []
}

files.logicRs:
// Custom Space — logic (Rust, compiled to wasm32). Same shape as the Rune
// starter: describe params / triggers by id, keep state, react to them.
// The panel binds to the ids (ui.knob('amount'), ui.button('go')).
use songbird_vibefx_sdk::EditorDescriptor;

songbird_vibefx_sdk::editor! {
    describe: EditorDescriptor::new("Space").knob("amount", 0.0, 1.0, 0.5).trigger("go"),

    state: { amount: f64 = 0.5 },

    param(state, id, value, _out) {
        if id == "amount" { state.amount = value; }
    }

    trigger(state, id, _args, out) {
        out.emit(id, serde_json::json!({ "amount": state.amount }));
    }
}

