// New space — panel. Compose the design-system builders
// and mount the tree once; `.link(id)` binds a knob to a param the logic declares,
// `button(id)` fires a declared trigger. The Docs pane has the full vocabulary.

mount(
  shell({ accent: 'teal' },
    section('New space', { icon: 'Activity' },
      knob().link('amount'),
      button('go', { label: 'Go' }))));
